import {readFileSync,writeFileSync,realpathSync,existsSync} from 'node:fs';
import {dirname,resolve,isAbsolute,posix} from 'node:path';
import {pathToFileURL} from 'node:url';
import {createHash} from 'node:crypto';
import {Worker,isMainThread,workerData} from 'node:worker_threads';
import {Session} from 'node:inspector';
import {getHeapStatistics,getHeapSpaceStatistics,writeHeapSnapshot} from 'node:v8';
const sha=x=>createHash('sha256').update(x).digest('hex');
const [requestPath,reportPath]=process.argv.slice(2);
if(isMainThread){
 if(process.argv.length!==4||!requestPath||!reportPath||existsSync(reportPath))throw Error('Expected REQUEST FRESH_REPORT');
 const worker=new Worker(new URL(import.meta.url),{workerData:{requestPath,reportPath},resourceLimits:{stackSizeMb:256,maxOldGenerationSizeMb:6144,maxYoungGenerationSizeMb:128}});
 await new Promise((done,reject)=>{worker.once('error',reject);worker.once('exit',n=>n===0?done():reject(Error('Heap probe worker exit '+n)));});
}else{
 const request=JSON.parse(readFileSync(workerData.requestPath,'utf8'));
 if(request.schemaVersion!==1||!['traffic','uncollected','snapshot'].includes(request.kind)||request.samplingIntervalBytes!==1048576)throw Error('Invalid heap probe request');
 const verify=()=>{for(const [path,digest]of Object.entries({...request.pins,...request.inputs}))if(realpathSync(path)!==path||sha(readFileSync(path))!==digest)throw Error('Pinned input drift: '+path);};
 verify();
 const {runTemplateSteps,runCheckerSteps}=await import(pathToFileURL(request.runtimeHelper).href);
 const {inspectorPost:post}=await import(pathToFileURL(request.profilerHelper).href);
 const tag=x=>typeof x?.$==='string'?x.$.split('.').at(-1):null;
 const items=x=>{const a=[];while(tag(x)==='Con'){a.push(x.head);x=x.tail;}if(tag(x)!=='Nil')throw Error('Malformed native list');return a;};
 const list=a=>a.reduceRight((tail,head)=>({$:'Con',head,tail}),{$:'Nil'});
 const end=Object.freeze({$:'FeedbackFuelEnd'}),fuelProto={get tail(){return fuel(this.remaining-1);}};
 const fuel=n=>{if(n===0)return end;const x=Object.create(fuelProto);x.$='FeedbackFuelCell';x.remaining=n;return x;};
 const result={schemaVersion:1,status:'RUNNING',diagnosticOnly:true,acceptanceEvidence:false,performanceEvidence:false,kind:request.kind,image:request.image,imageSha256:sha(readFileSync(request.image)),request:workerData.requestPath,requestSha256:sha(readFileSync(workerData.requestPath)),runtime:{versions:process.versions,execArgv:process.execArgv,heapLimitBytes:getHeapStatistics().heap_size_limit},workerPolicy:{stackMiB:256,oldGenerationMiB:6144,youngGenerationMiB:128},samplingIntervalBytes:request.samplingIntervalBytes,phases:[],boundaries:[],samples:[],stepCounts:{},note:'Actual own parser/expander/checker and unchanged opaque drivers; no image patch, AST replay or replacement checker. Diagnostics are not clean CPU/peak-RAM evidence. Uncollected samples may include garbage not yet collected; they are not strong-retention proof. A heap snapshot can induce GC and pause execution, and is a separate diagnostic prefix.'};
 const memory=()=>({memory:process.memoryUsage(),heapStatistics:getHeapStatistics(),spaces:getHeapSpaceStatistics()});
 const save=()=>writeFileSync(workerData.reportPath,JSON.stringify(result,null,2)+'\n');
 const phase=(name,action)=>{const start=performance.now(),cpu=process.cpuUsage();result.activePhase=name;save();const value=action(),used=process.cpuUsage(cpu);result.phases.push({phase:name,elapsedMs:performance.now()-start,userCpuMs:used.user/1000,systemCpuMs:used.system/1000,...memory()});delete result.activePhase;save();return value;};
 const startup=performance.now();
 const api=(await import(pathToFileURL(request.image).href)).default;
 result.phases.push({phase:'startup',elapsedMs:performance.now()-startup,...memory()});
 if(!request.exports.every(key=>typeof api?.[key]==='function'))throw Error('Compiler ABI incomplete');
 let modules=[],declarations=0;
 const seen=new Map();
 phase('load-parse',()=>{
  const active=new Set(),observed=new Set();
  const observe=path=>{const p=realpathSync(path);if(!Object.hasOwn(request.inputs,p))throw Error('Unexpected input '+p);observed.add(p);return p;};
  const namespace=(scope,path)=>path==='Base'?'':posix.normalize(isAbsolute(path)?path.replace(/\.bend$/,''):posix.dirname(scope)+'/'+path.replace(/\.bend$/,''));
  const visit=(file,scope)=>{
   const p=observe(file);if(active.has(p))throw Error('Import cycle');if(seen.has(p)){if(seen.get(p)!==scope)throw Error('Namespace mismatch');return;}
   seen.set(p,scope);active.add(p);
   const feedback=api.parse_with_fuel(fuel(8000000),p,readFileSync(p,'utf8'));
   if(tag(feedback)!=='FeedbackComplete'||tag(feedback.value.result)!=='ParseSuccess')throw Error('Own parse failure: '+p);
   const module=feedback.value.result.module;declarations+=items(module.declarations).length;
   for(const top of items(module.declarations))if(tag(top)==='DefTop'&&tag(top.definition.body)==='DefImports')for(const path of items(top.definition.body.paths))if(path.endsWith('.js'))observe(resolve(dirname(p),path));
   for(const imported of items(module.imports)){const path=imported.path;if(path.endsWith('.js'))observe(resolve(dirname(p),path));else if(!path.endsWith('.c'))visit(path==='Base'?resolve(request.repository,'bend2/base.bend'):resolve(dirname(p),path),namespace(scope,path));}
   modules.push(api.parsed_module(scope,module));active.delete(p);
  };
  visit(request.root,'');if(observed.size!==Object.keys(request.inputs).length)throw Error('Own parser omitted a frozen input');
  result.moduleCount=seen.size;result.sourceDeclarations=declarations;modules=list(modules);
 });
 let expanded=phase('expand',()=>runTemplateSteps({...api,expand_modules_start:input=>{modules=undefined;return api.expand_modules_start(input);}},modules,{onFinish(_,steps){result.stepCounts.expand=steps;}}));
 if(tag(expanded)!=='ExpandSuccess')throw Error('Own expansion failure');
 const session=new Session();session.connect();let sampling=false;
 const sample=(label,step,finish=false)=>{
  const profile=post(session,finish?'HeapProfiler.stopSampling':'HeapProfiler.getSamplingProfile').profile;
  const path=workerData.reportPath+'.'+label+'.heapprofile';writeFileSync(path,JSON.stringify(profile)+'\n',{flag:'wx'});
  result.samples.push({label,step,path,sha256:sha(readFileSync(path)),...memory()});if(finish)sampling=false;
 };
 const STOP=Object.freeze({snapshotPrefix:true});
 try{
  if(request.kind!=='snapshot'){
   post(session,'HeapProfiler.enable');post(session,'HeapProfiler.startSampling',{samplingInterval:request.samplingIntervalBytes,includeObjectsCollectedByMajorGC:request.kind==='traffic',includeObjectsCollectedByMinorGC:request.kind==='traffic'});sampling=true;
   post(session,'Profiler.enable');post(session,'Profiler.setSamplingInterval',{interval:1000});post(session,'Profiler.start');
  }
  let checked=phase('check',()=>runCheckerSteps(api,()=>{const input=expanded.modules;expanded=undefined;return api.check_expanded_start(input);},{
   onStep(step){
    if(request.milestones.includes(step)){
     result.boundaries.push({step,...memory()});
     if(request.kind==='snapshot'){
      const path=workerData.reportPath+'.heapsnapshot';if(existsSync(path))throw Error('Snapshot output already exists');
      result.snapshot={step,path,memoryBefore:memory(),implicitGC:true,notPeakMemoryEvidence:true};save();
      writeHeapSnapshot(path);result.snapshot.memoryAfter=memory();result.snapshot.sha256=sha(readFileSync(path));
      throw STOP;
     }
     sample('step-'+step,step);save();
    }
   },
   onFinish(_,steps){result.stepCounts.check=steps;}
  }));
  if(tag(checked)!=='CheckSuccess')throw Error('Own checking failure');
  checked=undefined;
  sample('finished',result.stepCounts.check,true);
  const cpuProfile=post(session,'Profiler.stop').profile,path=workerData.reportPath+'.cpuprofile';writeFileSync(path,JSON.stringify(cpuProfile)+'\n',{flag:'wx'});result.cpuProfile={path,sha256:sha(readFileSync(path)),scope:'check plus diagnostic sample serialization, worker isolate'};
  if(request.expected){for(const key of ['moduleCount','sourceDeclarations'])if(result[key]!==request.expected[key])throw Error('Unexpected '+key);if(JSON.stringify(result.stepCounts)!==JSON.stringify(request.expected.stepCounts))throw Error('Scheduler counts differ from frozen work');}
  result.status='PASS_FULL_OWN_CHECK_DIAGNOSTIC';
 }catch(error){if(error!==STOP)throw error;result.status='SNAPSHOT_PREFIX_ONLY_NOT_FULL_CHECK';}
 finally{if(sampling)post(session,'HeapProfiler.stopSampling');session.disconnect();}
 verify();result.finalMemory=memory();save();console.log(JSON.stringify({status:result.status,kind:result.kind,moduleCount:result.moduleCount,sourceDeclarations:result.sourceDeclarations,stepCounts:result.stepCounts,samples:result.samples.map(x=>({label:x.label,path:x.path})),snapshot:result.snapshot?{path:result.snapshot.path,step:result.snapshot.step}:undefined}));
}

